<script setup lang="ts">
import { computed, ref } from 'vue'
import dayjs from 'dayjs'
import { loadMachineProductionContext,type MachineProductionContext,type ProductionMetric,type TScadaData } from '../api/scada'
import { analyticsParams } from './myfunc/analyticsParams'
import { getShiftInfo,type ShiftInfo } from './myfunc/getShiftInfo'
import cnc60Image from '../assets/CNC60.png';import jg60Image from '../assets/JG60.png'
const props=defineProps<{sourceList?:TScadaData[]}>()
const list=computed(()=>props.sourceList||[])
const rows=computed(()=>Math.max(1,...list.value.map(item=>item.MachineID.trCount??0),...list.value.map(item=>item.MachineID.rowIndex??0)))
const cols=computed(()=>Math.max(1,...list.value.map(item=>item.MachineID.tdCount??0),...list.value.map(item=>item.MachineID.colIndex??0)))
const gridStyle=computed(()=>({'--rows':rows.value,'--cols':cols.value,'--cell-size':`${Math.max(38,Math.min(112,1320/cols.value))}px`,'--scale':Math.max(.36,Math.min(1,12/cols.value))}))
const position=(item:TScadaData)=>({gridRow:String(Math.max(1,item.MachineID.rowIndex??1)),gridColumn:String(Math.max(1,item.MachineID.colIndex??1))})
const image=(item:TScadaData)=>item.MachineID.MachineTypeIconUrl||(item.MachineID.Area?.trim()==='一楼'&&item.MachineID.Stype?.trim()==='M80'?jg60Image:cnc60Image)
const visible=ref(false),current=ref<TScadaData|null>(null),context=ref<MachineProductionContext|null>(null),loading=ref(false),error=ref(''),shift=ref<ShiftInfo|null>(null)
const status=(value:number|undefined)=>value===-1?'通讯异常':value===2?'待机':value===3?'报警':'运行'
const rate=(value:number|null)=>value===null?'—':`${value.toFixed(1)}%`
const toHourNo=(value:string)=>Number(value.replace(/[-: ]/g,'').slice(0,10)+'00')
const lastHours=computed(()=>context.value?.machine?.hourly.filter(item=>{const value=toHourNo(item.hour);return value>=Number(shift.value?.LastT1)&&value<Number(shift.value?.LastT2)})??[])
const currentHours=computed(()=>context.value?.machine?.hourly.filter(item=>{const value=toHourNo(item.hour);return value>=Number(shift.value?.ThisT1)&&value<Number(shift.value?.ThisT2)})??[])
const open=async(row:TScadaData)=>{current.value=row;visible.value=true;context.value=null;error.value='';loading.value=true;const currentShift=getShiftInfo(dayjs().format('YYYY-MM-DD HH:mm:ss'));shift.value=currentShift;const params=analyticsParams(row.MachineID.Area);params.hourlyStart=Number(currentShift.LastT1);params.hourlyEnd=params.currentEnd;try{context.value=await loadMachineProductionContext(row.MachineID.MachineID,params)}catch(e){error.value=e instanceof Error?e.message:'生产信息加载失败'}finally{loading.value=false}}
const metricLines=(item:ProductionMetric)=>[
  {kind:'standard',label:'标准',value:String(item.standard)},
  {kind:'actual',label:'实际',value:String(item.actual)},
  {kind:'rate',label:'达成',value:rate(item.rate)},
]
</script>
<template><div class="machine-grid" :style="gridStyle"><button v-for="item in list" :key="item.MachineID.MachineID" class="machine-cell" :class="`machine-status-${item.LedStatus}`" :style="position(item)" :title="`${item.MachineID.MachineNO} · ${status(item.LedStatus)}`" @click="open(item)"><img :src="image(item)" :alt="`${item.MachineID.MachineNO}机台`"/><span class="machine-state">{{item.MachineID.MachineNO}}</span></button></div>
  <div v-if="visible" class="machine-modal-mask" @click="visible=false"><article class="machine-modal" @click.stop><header><div><span>设备生产详情</span><h2>{{current?.MachineID.MachineNO}} - {{current?.MachineID.IpAddr||'未配置IP'}}</h2></div><button title="关闭" @click="visible=false">×</button></header><div class="machine-modal-body"><section class="machine-facts"><div><small>实时状态</small><strong :class="`state-text-${current?.LedStatus}`">{{status(current?.LedStatus)}}</strong></div><div><small>分钟产量</small><strong>{{current?.WkcntrSum??0}} pcs</strong></div><div><small>采集时点</small><strong>{{current?.ScadaNO}}</strong></div><div><small>连接地址</small><strong>{{current?.MachineID.IpAddr||'未配置'}}</strong></div><div><small>设备品牌</small><strong>{{current?.MachineID.Brand||'—'}}</strong></div><div><small>设备型号</small><strong>{{current?.MachineID.Model||'—'}}</strong></div><div><small>出厂日期</small><strong>{{current?.MachineID.OutDate?dayjs(current.MachineID.OutDate).format('YYYY-MM-DD'):'—'}}</strong></div><div><small>工件计数</small><strong>{{current?.WkcntrNum??0}}</strong></div></section><div v-if="loading" class="modal-state">正在读取产品与排产…</div><div v-else-if="error" class="report-error">{{error}}</div><template v-else><section class="current-product"><header><span>当前生产产品</span><b v-if="!context?.currentProduct">停产 / 未排产</b></header><div v-if="context?.currentProduct" class="product-data"><div><small>产品编码</small><strong>{{context.currentProduct.ProductCode}}</strong></div><div><small>产品名称</small><strong>{{context.currentProduct.ProductName}}</strong></div><div><small>规格型号</small><strong>{{context.currentProduct.Specification||'—'}}</strong></div><div><small>标准节拍</small><strong>{{context.currentProduct.Cavities}} pcs / {{context.currentProduct.CycleSeconds}} s</strong></div></div></section><section class="modal-section shift-section"><header><h3>上一班与当前班小时产量</h3><span>标准 / 实际 / 达成率</span></header><div class="shift-table"><table><tbody><tr class="shift-title"><th :colspan="Math.max(lastHours.length,1)">上一班（{{shift?.LastShift}}）</th></tr><tr class="shift-hours"><td v-if="!lastHours.length">无数据</td><td v-for="item in lastHours" :key="item.hour">{{item.hour.slice(5,13)}}</td></tr><tr class="shift-values"><td v-if="!lastHours.length">—</td><td v-for="item in lastHours" :key="item.hour"><span v-for="line in metricLines(item)" :key="line.kind"><em>{{line.label}}</em><b :class="`metric-value metric-value--${line.kind}`">{{line.value}}</b></span></td></tr><tr class="shift-title"><th :colspan="Math.max(currentHours.length,1)">当前班（{{shift?.ThisShift}}）</th></tr><tr class="shift-hours"><td v-if="!currentHours.length">无数据</td><td v-for="item in currentHours" :key="item.hour">{{item.hour.slice(5,13)}}</td></tr><tr class="shift-values"><td v-if="!currentHours.length">—</td><td v-for="item in currentHours" :key="item.hour"><span v-for="line in metricLines(item)" :key="line.kind"><em>{{line.label}}</em><b :class="`metric-value metric-value--${line.kind}`">{{line.value}}</b></span></td></tr></tbody></table></div></section><section class="modal-section"><header><h3>排产变更</h3></header><div class="schedule-list"><div v-if="!context?.schedules.length" class="modal-state">暂无排产记录</div><div v-for="item in context?.schedules" :key="item.ScheduleID"><time>{{dayjs(item.StartTime).format('MM-DD HH:mm')}}</time><strong>{{item.product?.ProductCode||'停产 / 排空'}}</strong><span>{{item.product?.ShortName||item.product?.ProductName||item.Note}}</span></div></div></section></template></div></article></div>
</template>
